const formulaData={
    'Φ = B·S·cosθ':{title:'磁通量计算',desc:'用于计算穿过某一面积的磁场总量',usage:'① 线圈在磁场中的面积固定时\n② 磁场方向与线圈平面有夹角时\n③ 判断磁通量大小变化',example:'B=0.5T, S=0.02m², θ=0°\nΦ = 0.5×0.02×1 = 0.01 Wb'},
    'E = B·L·v':{title:'法拉第电磁感应定律（切割）',desc:'导体棒切割磁感线时产生的感应电动势',usage:'① 导体棒在磁场中运动\n② 导体运动方向 ⊥ 磁场方向\n③ 单根导体棒切割',example:'B=0.3T, L=0.8m, v=15m/s\nE = 0.3×0.8×15 = 3.6 V'},
    'I = E/(R+r)':{title:'闭合电路欧姆定律',desc:'计算电路中的感应电流大小',usage:'① 已知电动势E\n② 已知总电阻(R+r)\n③ 求电流I',example:'E=3.6V, R=5Ω, r=0Ω\nI = 3.6/5 = 0.72 A'},
    'E = L·ΔI/Δt':{title:'自感电动势',desc:'线圈自身电流变化产生的电动势',usage:'① 开关接通/断开瞬间\n② 电流均匀变化时\n③ 线圈自感系数L已知',example:'L=0.5H, ΔI=2A, Δt=0.2s\nE = 0.5×(2/0.2) = 5 V'},
    'U₁/U₂ = N₁/N₂':{title:'变压器原理',desc:'理想变压器原副线圈电压比等于匝数比',usage:'① 理想变压器\n② 交流电路\n③ 已知匝数比或电压比',example:'N₁=2200, N₂=110, U₁=220V\nU₂ = 220×(110/2200) = 11 V'},
    '楞次定律':{title:'感应电流方向判断',desc:'感应电流的磁场总是阻碍原磁通量的变化',usage:'① 判断电流方向\n② "增反"：磁通量增加，感应电流产生反向磁场\n③ "减同"：磁通量减少，感应电流产生同向磁场',example:'N极靠近线圈\n→ 磁通量↑\n→ 感应磁场↓(反向)\n→ 电流逆时针(俯视)'}
};
const quizData=[
    {formula:'Φ = B·S·cosθ',q:'计算穿过线圈的磁通量时用？',opts:['导体切割磁感线','线圈在磁场中面积不变','磁通量变化率','电流变化率'],ans:1},
    {formula:'E = B·L·v',q:'导体棒在磁场中做切割运动时用？',opts:['计算磁通量','计算感应电流','计算切割产生的电动势','计算自感'],ans:2},
    {formula:'I = E/(R+r)',q:'已知电动势和电阻，求电流用？',opts:['法拉第定律','楞次定律','欧姆定律','变压器'],ans:2}
];
let currentQuiz=0;
let quizAnswered=false;
document.querySelectorAll('.formula-card').forEach(card=>{
    card.addEventListener('click',()=>{
        const f=card.dataset.formula;
        const d=formulaData[f];
        const detail=document.getElementById('formula-detail');
        detail.innerHTML=`<div style="text-align:left;max-width:500px;margin:0 auto;">
            <h3 style="color:#667eea;margin-bottom:10px;">📌 ${d.title}</h3>
            <p style="color:#555;line-height:1.6;"><strong>公式：</strong>${f}</p>
            <p style="color:#555;line-height:1.6;"><strong>说明：</strong>${d.desc}</p>
            <p style="color:#555;line-height:1.6;white-space:pre-line;"><strong>使用场景：</strong>${d.usage}</p>
            <p style="color:#666;line-height:1.6;background:#fff3cd;padding:10px;border-radius:5px;margin-top:10px;"><strong>例题：</strong>${d.example}</p>
        </div>`;
        window.HeurisStage.emit('formula-view',{formula:f,title:d.title});
        if(quizData.some(q=>q.formula===f)){
            startQuiz(quizData.findIndex(q=>q.formula===f));
        }
    });
});
function startQuiz(idx){
    if(idx>=quizData.length)return;
    currentQuiz=idx;
    quizAnswered=false;
    const q=quizData[idx];
    const section=document.getElementById('quiz-section');
    section.style.display='block';
    const container=document.getElementById('quiz-options');
    container.innerHTML=`<p style="margin-bottom:10px;">${q.q}</p>`;
    q.opts.forEach((opt,i)=>{
        const btn=document.createElement('button');
        btn.className='quiz-btn';
        btn.textContent=opt;
        btn.onclick=()=>handleAnswer(btn,i,q.ans);
        container.appendChild(btn);
    });
}
function handleAnswer(btn,selected,correct){
    if(quizAnswered)return;
    quizAnswered=true;
    const btns=document.querySelectorAll('.quiz-btn');
    btns.forEach((b,i)=>{
        b.disabled=true;
        if(i===correct)b.classList.add('correct-answer');
        else if(i===selected&&i!==correct)b.classList.add('wrong-answer');
    });
    const isCorrect=selected===correct;
    window.HeurisStage.emit('quiz-answer',{question:quizData[currentQuiz].q,selected:quizData[currentQuiz].opts[selected],correct:quizData[currentQuiz].opts[correct],isCorrect});
    if(currentQuiz<quizData.length-1){
        setTimeout(()=>startQuiz(currentQuiz+1),1500);
    }
}

